167	    // regardless of whether that new pick succeeds, is canceled, or
168	    // throws — the earlier code only deleted it on success, leaking it
169	    // on every other exit path.
170	    final previousPath = current is PhotoError ? current.path : null;
171	    if (previousPath != null) {
172	      unawaited(_deletePickedFile(previousPath));
