268	  /// error or a generic OCR-call failure ([PhotoError.text] `null`). A
269	  /// no-op for [PhotoErrorKind.payloadTooLarge] (I/O matrix: no retry
270	  /// offered) and for a generic *save* failure (non-null [PhotoError.
271	  /// text]) — that case's own retry is tapping Salvar again, handled by
272	  /// [save] directly, mirroring `AudioEntryCubit.retry()`.
273	  Future<void> retry() async {
274	    final current = state;
275	    if (current is! PhotoError ||
276	        current.text != null ||
277	        current.kind == PhotoErrorKind.payloadTooLarge) {
278	      return;
279	    }
280	    final generation = ++_generation;
281	    emit(PhotoProcessing(path: current.path, mimeType: current.mimeType));
282	    await _recognize(current.path, current.mimeType, generation);
283	  }
284	
285	  /// "Salvar só a foto" — only valid from an [OcrNoText] error; saves the
286	  /// fixed, non-empty placeholder content (the contract's
287	  /// `content.minLength: 1` forbids an empty save).
288	  Future<void> saveWithoutText() async {
289	    final current = state;
290	    if (current is! PhotoError || current.kind != PhotoErrorKind.ocrNoText) {
291	      return;
292	    }
293	    await _save(
294	      path: current.path,
295	      mimeType: current.mimeType,
296	      text: _noTextPlaceholder,
297	    );
298	  }
299	
300	  /// Mirrors the Texto/Áudio fields' own `updateText` — keeps the
301	  /// recognized text editable before Salvar, and keeps a save-failure
302	  /// retry's text editable too (same as `AudioEntryCubit.updateText`'s
303	  /// own `AudioError` branch).
304	  void updateText(String text) {
305	    final current = state;
306	    if (current is PhotoRecognized && !current.saving) {
307	      emit(current.copyWith(text: text));
308	    } else if (current is PhotoError &&
